  14:[
    {k:"regla",titulo:"Presente simple como futuro",regla:"Para horarios fijos —camiones, aviones, clases, formaciones— se usa el presente simple, no el futuro: 'The bus from Dallas arrives early tomorrow morning.'",bien:"The bus arrives at 07:30 tomorrow.",mal:"The bus will arrive at 07:30 tomorrow, I think.",porque:"Un horario publicado es un hecho programado: va en presente simple.",en:"The bus from Dallas arrives early tomorrow morning."},
    {k:"idea",audio:"Can you change a flat tire? First you take out the jack and the spare tire. Then you loosen the nuts, you lift the car, and you replace the tire. The mechanic's class starts at eight tomorrow if you want to practice.",en:"The mechanic's class starts at eight tomorrow.",es:"La clase del mecánico empieza a las ocho mañana.",ops:["Explica cómo cambiar una llanta.","Vende llantas nuevas.","Reporta un choque en la carretera."],correcta:0},
    {k:"dosc",audio:"The train leaves at six tomorrow.",en:"The train leaves at six tomorrow.",a:"The train leaves at six tomorrow.",b:"The train is leaving at six tomorrow, maybe.",correcta:0},
    {k:"hueco",antes:"The bus from Dallas ",despues:" early tomorrow morning.",es:"El camión de Dallas llega mañana temprano.",ops:["arrives","is arriving","will arrive"],correcta:0},
    {k:"hueco",antes:"First you ",despues:" the nuts, then you lift the car.",es:"Primero aflojas las tuercas, luego levantas el carro.",ops:["loosen","loosening","are loosening"],correcta:0},
    {k:"model",en:"The formation starts at 06:00 tomorrow.",es:"La formación empieza a las 06:00 mañana."},
    {k:"model",en:"First you take out the spare tire.",es:"Primero sacas la llanta de repuesto."},
    {k:"model",en:"The flight leaves on Friday at noon.",es:"El vuelo sale el viernes al mediodía."},
    {k:"ask",q:"What time does your first class start tomorrow?",es:"¿A qué hora empieza tu primera clase mañana?",meta:"It starts at seven.",pista:"Usa el presente simple: It starts at..."},
    {k:"ask",q:"Explain in three steps how to change a flat tire.",es:"Explica en tres pasos cómo cambiar una llanta.",meta:"First you loosen the nuts, then you lift the car, then you replace the tire.",pista:"First you... then you... then you..."},
    {k:"transf",origen:"The bus will arrive at seven. (es el horario oficial)",pide:"Dilo como horario, en presente simple.",meta:"The bus arrives at seven.",pista:"The bus arrives..."},
    {k:"transf",solo:"alto",origen:"He is not going to fix the tire himself.",pide:"Usa el causativo: have something done.",meta:"He's going to have the tire changed.",pista:"...have the tire..."}
  ],
  15:[
    {k:"regla",titulo:"Would/Could para solicitudes · Reported commands",regla:"'Would/Could you' para solicitudes formales. 'Told/asked + to + infinitivo' para reportar órdenes.",bien:"Would you introduce your family? / He asked me to fill out the form.",mal:"He asked me that I fill out the form.",porque:"Después de asked/told + objeto va 'to + infinitivo', nunca 'that'.",en:"Could you please show me your identification?"},
    {k:"idea",audio:"At the military ceremony, the general asked the officer to introduce his family. He said: Would you please introduce your family to us? The officer replied: Of course, sir. He told his wife and children to stand up.",en:"Would you please introduce your family to the group?",es:"¿Podría presentar a su familia al grupo, por favor?",ops:["Un oficial presenta a su familia en una ceremonia.","Un oficial recibe una medalla.","Un cadete conoce a sus compañeros."],correcta:0},
    {k:"hueco",antes:"He asked me ",despues:" out the form.",es:"Me pidió que llenara el formulario.",ops:["to fill","filling","fill"],correcta:0},
    {k:"model",en:"Would you please introduce your family?",es:"¿Podría presentar a su familia, por favor?"},
    {k:"model",en:"She told me to fill out the form.",es:"Ella me dijo que llenara el formulario."},
    {k:"ask",q:"What did the general ask the officer to do?",es:"¿Qué le pidió el general al oficial que hiciera?",meta:"He asked him to introduce his family.",pista:"He asked him to..."},
    {k:"transf",origen:"Show me your ID.",pide:"Conviértela en solicitud cortés con 'Could you...'",meta:"Could you show me your ID?",pista:"Could you show me..."}
  ],
  16:[
    {k:"regla",titulo:"Be able to — habilidad en todos los tiempos",regla:"'Be able to' = 'can' pero funciona en todos los tiempos verbales.",bien:"I was able to finish the report on time.",mal:"I could to finish the report.",porque:"'Could to' no existe. Usa 'was/were able to' para habilidad específica en el pasado.",en:"She was able to fix the problem."},
    {k:"idea",audio:"At the job interview, the officer asked: What kind of work can you do? The cadet answered: I am able to speak English and Spanish. I was able to fix computers in my last job. I will be able to learn new skills quickly.",en:"What kind of work are you able to do?",es:"¿Qué tipo de trabajo eres capaz de hacer?",ops:["Un cadete describe sus habilidades en una entrevista.","Un cadete pide un aumento de salario.","Un oficial evalúa el entrenamiento físico."],correcta:0},
    {k:"hueco",antes:"She ",despues:" finish the report on time.",es:"Ella pudo terminar el informe a tiempo.",ops:["was able to","is able to","will able to"],correcta:0},
    {k:"model",en:"I am able to speak English and Spanish.",es:"Soy capaz de hablar inglés y español."},
    {k:"model",en:"I was able to finish the mission on time.",es:"Pude terminar la misión a tiempo."},
    {k:"ask",q:"What kind of work are you able to do?",es:"¿Qué tipo de trabajo eres capaz de hacer?",meta:"I am able to work in a team and follow orders.",pista:"I am able to..."},
    {k:"transf",origen:"I can speak English.",pide:"Cámbiala usando 'be able to'.",meta:"I am able to speak English.",pista:"I am able to..."}
  ],
  17:[
    {k:"regla",titulo:"How far / How long · Impersonal it",regla:"'How far' para distancia; 'How long' para duración. 'It' como sujeto impersonal para clima, distancia y tiempo.",bien:"It takes about six hours to drive there.",mal:"Takes about six hours to drive there.",porque:"En inglés las oraciones necesitan sujeto. 'It' es el sujeto impersonal.",en:"How long does it take to drive there?"},
    {k:"idea",audio:"Two soldiers were talking about a road trip. One asked: How far is it from El Paso to Houston? The other said: It's about seven hundred miles. How long does it take? It takes about ten hours. That's a long drive!",en:"How far is it from El Paso to Houston?",es:"¿Qué tan lejos está El Paso de Houston?",ops:["Dos soldados hablan sobre un viaje por carretera.","Dos soldados hablan sobre el clima.","Un soldado pide indicaciones."],correcta:0},
    {k:"hueco",antes:"",despues:" takes about three hours to get there.",es:"Toma aproximadamente tres horas llegar allá.",ops:["It","He","There"],correcta:0},
    {k:"model",en:"How far is it from El Paso to Houston?",es:"¿Qué tan lejos está El Paso de Houston?"},
    {k:"model",en:"It takes about ten hours to drive there.",es:"Toma aproximadamente diez horas manejar allá."},
    {k:"ask",q:"How far is it from Mexico City to Guadalajara?",es:"¿Qué tan lejos está la Ciudad de México de Guadalajara?",meta:"It's about three hundred miles. It takes about five hours by car.",pista:"It's about three hundred miles..."},
    {k:"transf",origen:"The distance is five hundred miles.",pide:"Conviértela en pregunta con 'How far...'",meta:"How far is it?",pista:"How far is it from..."}
  ]
